class Socket {
public:
  Socket(Socket&&) = default;                  // ownership can be transferred
  Socket& operator=(Socket&&) = default;
  Socket(const Socket&) = delete;              // copying is meaningless
  Socket& operator=(const Socket&) = delete;
  explicit Socket(int fd) : fd_(fd) {}
  ~Socket() { if (fd_ >= 0) ::close(fd_); }
private:
  int fd_;
};

