class FileHandle : private boost::noncopyable {   // an implementation detail
public:
  explicit FileHandle(int fd);
  ~FileHandle();
private:
  int fd_;
};

template <class T>
class NonCopyable {
protected:
  NonCopyable() {}
  ~NonCopyable() {}
private:
  NonCopyable(const NonCopyable&);   // declared, never defined
  T& operator=(const T&);            // declared, never defined
};

class Session : private NonCopyable<Session> {};
static_assert(!std::is_copy_assignable<Session>::value, "Session must not be copy-assigned");
